String sql = "INSERT INTO users (name, email) VALUES (?, ?)";
try (PreparedStatement ps =
        con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) { // opt in
    ps.setString(1, "Ravi");
    ps.setString(2, "ravi@x.com");
    ps.executeUpdate();
    try (ResultSet keys = ps.getGeneratedKeys()) {
        if (keys.next()) {
            long newId = keys.getLong(1);   // the auto-generated PK
            System.out.println("new id: " + newId);
        }
    }
}
